INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 6, 'theory', 'Quiz: function pointers and generic code');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 6, 0, 'What does the declaration int (*op)(int, int); mean?', '["A function returning a pointer to int", "An array of two pointers", "A pointer to a function with two ints returning int", "A pointer to two ints"]', 2, 'Read inside out: op is a pointer (*op) to a function with parameters (int, int) returning int. The parentheses around the star are mandatory: without them you would get a function returning int *.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 6, 1, 'Why is return x - y; a bad idea in a comparison function for qsort?', '["The difference can overflow and give the wrong sign", "qsort accepts only the values 0 and 1", "Subtraction is slower than comparison", "You can''t subtract ints"]', 0, 'For values of large magnitude the difference falls outside the int range: that is undefined behavior or a wrong sign. The safe form is (x > y) - (x < y).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 6, 2, 'What does the comparison function get from qsort when sorting an array of char *?', '["The strings themselves, of type char", "The string lengths", "The element indexes", "Pointers to the array cells, that is, pointers to char *"]', 3, 'qsort passes the addresses of array elements. The element is a char *, so the element''s address is a char * const *: first cast, then dereference, and only then call strcmp.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 6, 3, 'Why is void *ctx passed alongside a callback pointer?', '["So the callback can return a value", "To give the callback data: the pair \"function + context\" replaces a closure", "To speed up the call", "So the compiler checks the types"]', 1, 'A function in C has no captured variables. The context is a manual closure: the caller is responsible for keeping it alive until the last call of the callback.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 6, 4, 'What does a table of function pointers give you instead of a long switch?', '["Type safety without casts", "One indirect jump instead of a chain of comparisons; a new case is a new line in the table", "The ability to inline the function body at the call site", "No indirect jumps at all"]', 1, 'The index picks the handler in constant time. The price is the indirect jump: it is harder for the compiler to optimize and to inline the function body.');
